void AverageHp()
{
    SetStatus("All");
    int total = 0; int minMaxHp = 0; int count = 0;
    ForAllStatus(status => { 
        if (status.GetBuff(DataId.buff_lifelink) == null) return; 
        if (count == 0) minMaxHp = status.MaxHp; 
        else minMaxHp = minMaxHp > status.MaxHp ? status.MaxHp : minMaxHp; 
        total += status.CurHp; count += 1; 
        });
    if (count <= 1) return; 
    int even = total / count; even = even > minMaxHp ? minMaxHp : even; 
    SetStatus(Object.Where(x => x.GetBuff(DataId.buff_lifelink) != null));
    SetHp(even.ToString());
}
